CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,profile TEXT NOT NULL);
CREATE TABLE memberships(user_id TEXT NOT NULL,workspace_id TEXT NOT NULL,PRIMARY KEY(user_id,workspace_id));
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL,csrf TEXT NOT NULL,expires REAL NOT NULL);
CREATE TABLE campaigns(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,title TEXT NOT NULL,state TEXT NOT NULL,document TEXT NOT NULL,created TEXT NOT NULL,updated TEXT NOT NULL);
CREATE INDEX campaigns_workspace ON campaigns(workspace_id);
CREATE TABLE assets(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,campaign_id TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,digest TEXT NOT NULL,body BLOB NOT NULL,status TEXT NOT NULL,created TEXT NOT NULL);
CREATE TABLE approvals(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,campaign_id TEXT NOT NULL,asset_id TEXT NOT NULL,digest TEXT NOT NULL,user_id TEXT NOT NULL,created TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE jobs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,campaign_id TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,priority INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,available REAL NOT NULL,lease REAL,idem TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,error TEXT,created TEXT NOT NULL,UNIQUE(workspace_id,idem));
CREATE INDEX jobs_claim ON jobs(status,available,priority);
CREATE TABLE events(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id TEXT NOT NULL,campaign_id TEXT,actor TEXT NOT NULL,kind TEXT NOT NULL,detail TEXT NOT NULL,created TEXT NOT NULL);
